def retain_existing_active_periods(apps, schema_editor):
    Ledger = apps.get_model("members", "MemberLedger")
    Period = apps.get_model("members", "MemberActivePeriod")
    alias = schema_editor.connection.alias
    for ledger in (
        Ledger.objects.using(alias)
        .filter(status="active", member__status="active")
        .select_related("member")
        .iterator()
    ):
        Period.objects.using(alias).create(
            member_id=ledger.member_id,
            ledger_id=ledger.pk,
            started_at=timezone.make_aware(
                datetime.combine(ledger.member.admit_date, time.min)
            ),
            imported=True,
        )


